output_text:
[
  {
    "id": "walk_only_single_file_aisles",
    "text": "Shopping carts are not allowed in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "A cart must not be pushed from an open aisle into a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_only_at_walkin_mouths",
    "text": "When a cart is temporarily parked for walk-in shelf access, it should only be dropped at the broad mouth of a single-file aisle.",
    "abstraction": {
      "state_properties": {
        "walkInAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "walkInAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_after_walkin_item",
    "text": "After taking an item on foot in a single-file aisle, the agent must return to the aisle mouth and retrieve the cart before exiting.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "walkInAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "footShelfInteractionInSingleFile": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileAisle",
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "walkInAisleMouth",
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "footShelfInteractionInSingleFile",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "cart_required_in_compact_service_zones",
    "text": "Shelf interactions in compact cart-service zones, such as two-wide side bays or short vertical shelf approaches, must be done while holding the cart.",
    "abstraction": {
      "state_properties": {
        "twoWideSideBay": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthH",
                2
              ]
            }
          ]
        },
        "shortVerticalShelfApproach": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        },
        "compactCartServiceZone": {
          "or": [
            "twoWideSideBay",
            "shortVerticalShelfApproach"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "compactCartServiceZone",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "facing_shelves_are_walkin_only",
    "text": "Aisles with shelves on both sides are walk-in-only, so shelf interaction there may not be performed with a cart.",
    "abstraction": {
      "state_properties": {
        "betweenFacingShelves": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "betweenFacingShelves",
          "INTERACT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "cart_handling_only_in_clear_zones",
    "text": "Changing cart possession should happen only in broad non-shelf cart-handling zones, not beside merchandise shelves or in cramped shelf bays.",
    "abstraction": {
      "state_properties": {
        "clearCartHandlingZone": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        },
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartPossessionChange": {
          "pre": {
            "or": [
              "pickUpCart",
              "dropCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartPossessionChange",
          {
            "not": "clearCartHandlingZone"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_wandering_in_shopping_area",
    "text": "After parking a cart, a cartless shopper may move only within the associated single-file aisle or its mouth, not wander around the shopping floor.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "walkInAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "shoppingVicinity": {
          "or": [
            "adjShelf",
            "singleFileAisle",
            "walkInAisleMouth"
          ]
        },
        "cartlessAllowedArea": {
          "or": [
            "singleFileAisle",
            "walkInAisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          "shoppingVicinity",
          {
            "not": "cartlessAllowedArea"
          }
        ]
      }
    }
  }
]
